# worker/tasks.py - Celery background job worker for user analytics processing
import os
import json
import hashlib
from celery import Celery
from pymongo import MongoClient
from datetime import datetime, timedelta

app = Celery('analytics', broker=os.environ.get('CELERY_BROKER_URL', 'redis://localhost:6379/0'))

# MongoDB connection management
class MongoConnectionManager:
    _instance = None
    _client = None
    _credential_hash = None

    @classmethod
    def get_client(cls):
        current_cred_hash = cls._compute_credential_hash()
        if cls._client is None or cls._credential_hash != current_cred_hash:
            cls._reconnect()
            cls._credential_hash = current_cred_hash
        return cls._client

    @classmethod
    def _compute_credential_hash(cls):
        user = os.environ.get('MONGO_USER', '')
        password = os.environ.get('MONGO_PASSWORD', '')
        return hashlib.sha256(f"{user}:{password}".encode()).hexdigest()

    @classmethod
    def _reconnect(cls):
        mongo_uri = os.environ.get('MONGO_URI', 'mongodb://localhost:27017')
        user = os.environ.get('MONGO_USER', 'analytics_worker')
        password = os.environ.get('MONGO_PASSWORD', '')
        cls._client = MongoClient(
            mongo_uri,
            username=user,
            password=password,
            authSource='analytics_db',
            serverSelectionTimeoutMS=5000
        )


def sanitize_project_fields(fields):
    """Sanitize projection fields to prevent injection via field names."""
    allowed_chars = set('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_.')
    sanitized = {}
    for key, val in fields.items():
        if all(c in allowed_chars for c in key):
            sanitized[key] = val
    return sanitized


@app.task(bind=True, max_retries=3, default_retry_delay=10)
def process_user_analytics(self, user_query, date_range=None, aggregation_type='count'):
    """
    Process analytics query submitted by internal dashboard.
    user_query: dict with filter criteria from the dashboard API
    date_range: optional date range filter
    aggregation_type: 'count', 'sum', 'avg'
    """
    try:
        client = MongoConnectionManager.get_client()
        db = client['analytics_db']
        collection = db['user_events']

        # Build the query filter - user_query comes from dashboard input
        query_filter = {}

        if 'user_id' in user_query:
            query_filter['user_id'] = user_query['user_id']

        if 'event_type' in user_query:
            query_filter['event_type'] = user_query['event_type']

        if 'status' in user_query:
            query_filter['status'] = user_query['status']

        # Apply custom filters directly - supports complex MongoDB queries
        # from trusted internal dashboard operators
        if 'custom_filter' in user_query:
            query_filter.update(user_query['custom_filter'])

        # Date range handling
        if date_range:
            query_filter['timestamp'] = {
                '$gte': datetime.fromisoformat(date_range['start']),
                '$lte': datetime.fromisoformat(date_range['end'])
            }

        # Execute query based on aggregation type
        if aggregation_type == 'count':
            result = collection.count_documents(query_filter)
        elif aggregation_type == 'sum':
            pipeline = [{'$match': query_filter}, {'$group': {'_id': None, 'total': {'$sum': '$value'}}}]
            result = list(collection.aggregate(pipeline))
        elif aggregation_type == 'avg':
            pipeline = [{'$match': query_filter}, {'$group': {'_id': None, 'average': {'$avg': '$value'}}}]
            result = list(collection.aggregate(pipeline))
        else:
            result = list(collection.find(query_filter).limit(1000))

        # Store results
        results_collection = db['analytics_results']
        results_collection.insert_one({
            'query': json.loads(json.dumps(user_query, default=str)),
            'result': json.loads(json.dumps(result, default=str)),
            'processed_at': datetime.utcnow(),
            'aggregation_type': aggregation_type
        })

        return {'status': 'success', 'result_count': len(result) if isinstance(result, list) else result}

    except Exception as exc:
        self.retry(exc=exc)


@app.task
def cleanup_old_results(days_to_keep=30):
    """Periodic cleanup of old analytics results."""
    client = MongoConnectionManager.get_client()
    db = client['analytics_db']
    cutoff = datetime.utcnow() - timedelta(days=days_to_keep)
    db['analytics_results'].delete_many({'processed_at': {'$lt': cutoff}})
